export interface ShopifyOrderWebhookPayload {
  id: number
  name: string
  email: string
  total_price: string
  currency: string
  created_at: string
  line_items: Array<{ title: string; quantity: number }>
}

export interface ConnectorConfig {
  shopifyClientSecret: string
  slackBotToken: string
  slackChannel: string
  hmacSignature?: string
  rawBody?: string
  fetch?: typeof fetch
}

export interface HandleResult {
  slackMessageTs: string
  slackChannel: string
}

function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false
  let result = 0
  for (let i = 0; i < a.length; i++) {
    result |= a.charCodeAt(i) ^ b.charCodeAt(i)
  }
  return result === 0
}

async function verifyHmac(
  secret: string,
  rawBody: string,
  signature: string
): Promise<void> {
  const encoder = new TextEncoder()
  const keyData = encoder.encode(secret)
  const messageData = encoder.encode(rawBody)
  const cryptoKey = await crypto.subtle.importKey(
    'raw',
    keyData,
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  )
  const signatureBuffer = await crypto.subtle.sign('HMAC', cryptoKey, messageData)
  const expectedSignature = Array.from(new Uint8Array(signatureBuffer))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('')
  if (!timingSafeEqual(expectedSignature, signature.toLowerCase())) {
    throw new Error('Invalid HMAC signature')
  }
}

function formatSlackMessage(payload: ShopifyOrderWebhookPayload): string {
  const lineItemsText = payload.line_items
    .map((item) => `${item.title} (qty: ${item.quantity})`)
    .join(', ')
  return (
    `New order ${payload.name} from ${payload.email} for ` +
    `$${payload.total_price} ${payload.currency}\n` +
    `Order ID: ${payload.id}\n` +
    `Created: ${payload.created_at}\n` +
    `Items: ${lineItemsText}`
  )
}

export async function handle(
  payload: ShopifyOrderWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.id) throw new Error('Missing required field: id')
  if (!payload.name) throw new Error('Missing required field: name')
  if (!payload.email) throw new Error('Missing required field: email')
  if (!payload.total_price) throw new Error('Missing required field: total_price')
  if (!payload.currency) throw new Error('Missing required field: currency')
  if (!payload.created_at) throw new Error('Missing required field: created_at')
  if (!payload.line_items || !Array.isArray(payload.line_items)) {
    throw new Error('Missing required field: line_items')
  }

  if (config.hmacSignature && config.rawBody) {
    await verifyHmac(config.shopifyClientSecret, config.rawBody, config.hmacSignature)
  }

  const text = formatSlackMessage(payload)

  const response = await fetchImpl('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      channel: config.slackChannel,
      text,
    }),
  })

  if (!response.ok) {
    throw new Error(
      `Slack API error: ${response.status} ${response.statusText} at POST https://slack.com/api/chat.postMessage`
    )
  }

  const data = (await response.json()) as { ok: boolean; channel: string; ts: string }
  if (!data.ok) {
    throw new Error('Slack API returned ok: false')
  }

  return {
    slackMessageTs: data.ts,
    slackChannel: data.channel,
  }
}

